/** Fast check if lat/lng is within the fine Odisha landmass silhouette */
export function isInsideOdishaMask(lat: number, lng: number): boolean {
  if (lat < 17.60 || lat > 22.67 || lng < 81.13 || lng > 87.78) return false;
  const gx = Math.floor(((lng - 81.13) / (87.78 - 81.13)) * 64);
  const gy = Math.floor(((22.67 - lat) / (22.67 - 17.60)) * 50);
  if (gx < 0 || gx >= 64 || gy < 0 || gy >= 50) return false;
  return BIT_GRID[gy][gx] === "1";
}
